(()=>{const out={atob:[],btoa:[]};for(const s of ['', 'YQ','YQ=','YQ==','YQ===','=','==','===','A','AA','AAA','AAAA','AB',' Y Q ==','\vYQ==','-_','AA=','AAA=',null,undefined,Symbol('x')]){try{out.atob.push([String(s),Array.from(atob(s),c=>c.charCodeAt(0)),null])}catch(e){out.atob.push([String(s),null,e.name])}}for(const s of ['', 'abc','\u00ff','\u0100',null,undefined,Symbol('x')]){try{out.btoa.push([String(s),btoa(s),null])}catch(e){out.btoa.push([String(s),null,e.name])}}out.shape=[];for(const f of [atob,btoa]){let missing,construct;try{f()}catch(e){missing=e.name}try{new f('')}catch(e){construct=e.name}out.shape.push([f.name,f.length,String(f),missing,construct])}return out})()
